import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        long q = k;

        if (k == 0) {
            System.out.println(powerMod(p, p - 1));
            sc.close();
            return;
        }
        if (k == 1) {
            System.out.println(powerMod(p, p));
            sc.close();
            return;
        }

        int cycle = 1;
        while (q != 1) {
            q = (q * k) % p;
            cycle++;
        }
        System.out.println(powerMod(p, (p - 1) / cycle));
        sc.close();
    }

    public static long powerMod(long base, long exponent) {
        long result = 1;
        long currentPower = base;
        long e = exponent;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * currentPower) % MOD;
            }
            currentPower = (currentPower * currentPower) % MOD;
            e >>= 1;
        }
        return result;
    }
}
